// newObj allocates a table object of the tag, or nil.
func newObj(tag uint64) any {
	switch tag {
	case 1:
		return new(ArrayType)
	case 2:
		return new(AsPattern)
	case 3:
		return new(AssertStmt)
	case 4:
		return new(AssignStmt)
	case 5:
		return new(BasicLit)
	case 6:
		return new(BinaryExpr)
	case 7:
		return new(BlockStmt)
	case 8:
		return new(BranchStmt)
	case 9:
		return new(CallExpr)
	case 10:
		return new(CaseClause)
	case 11:
		return new(CatchArm)
	case 12:
		return new(CatchExpr)
	case 13:
		return new(Comment)
	case 14:
		return new(CommentGroup)
	case 15:
		return new(CompositeLit)
	case 16:
		return new(ContextBody)
	case 17:
		return new(ContextDecl)
	case 18:
		return new(ContextEntry)
	case 19:
		return new(ContextLit)
	case 20:
		return new(DeclStmt)
	case 21:
		return new(ErrorRow)
	case 22:
		return new(ExprStmt)
	case 23:
		return new(ExternSpec)
	case 24:
		return new(Field)
	case 25:
		return new(FieldList)
	case 26:
		return new(File)
	case 27:
		return new(ForStmt)
	case 28:
		return new(FuncDecl)
	case 29:
		return new(FuncLit)
	case 30:
		return new(FuncType)
	case 31:
		return new(Ident)
	case 32:
		return new(IfStmt)
	case 33:
		return new(ImportDecl)
	case 34:
		return new(ImportSpec)
	case 35:
		return new(IndexExpr)
	case 36:
		return new(InterfaceType)
	case 37:
		return new(InterpolatedString)
	case 38:
		return new(KeyValueExpr)
	case 39:
		return new(LawDecl)
	case 40:
		return new(LawReach)
	case 41:
		return new(LawRewrite)
	case 42:
		return new(MachineEntry)
	case 43:
		return new(MachineType)
	case 44:
		return new(MapType)
	case 45:
		return new(NeedsClause)
	case 46:
		return new(ParenExpr)
	case 47:
		return new(ProvidesClause)
	case 48:
		return new(RangeStmt)
	case 49:
		return new(ReturnStmt)
	case 50:
		return new(SelectorExpr)
	case 51:
		return new(SliceExpr)
	case 52:
		return new(StarExpr)
	case 53:
		return new(StructType)
	case 54:
		return new(SwitchStmt)
	case 55:
		return new(TakesClause)
	case 56:
		return new(TestDecl)
	case 57:
		return new(TryExpr)
	case 58:
		return new(TupleExpr)
	case 59:
		return new(TypeDecl)
	case 60:
		return new(TypeGuard)
	case 61:
		return new(TypeSwitchStmt)
	case 62:
		return new(UnaryExpr)
	case 63:
		return new(VarDecl)
	case 64:
		return new(VarSpec)
	case 65:
		return new(VariantSpec)
	}
	return nil
}

